<div class="d-flex justify-content-between align-items-center mb-4"><h2>Users</h2></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0 admin-table"><thead><tr><th class="no-sort">Image</th><th>Name</th><th>Email</th><th>Mobile</th><th>Address</th><th class="no-sort">Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?php if(!empty($u->image)): ?><img class="thumb" src="<?= product_image_url($u->image) ?>"><?php else: ?><div class="rounded-circle bg-light text-secondary d-flex align-items-center justify-content-center" style="width:44px;height:44px"><i class="fa-solid fa-user"></i></div><?php endif; ?></td><td><?= html_escape($u->name) ?></td><td><?= html_escape($u->email) ?></td><td><?= html_escape($u->mobile) ?></td><td><?= html_escape($u->address) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/users/edit/'.$u->id) ?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="<?= site_url('admin/users/delete/'.$u->id) ?>" onclick="return confirm('Delete this user?')">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></div>
